static const uint8_t plusrom_trap_bitmap[96] = {
    0x00, 0x07, 0xF7, 0xFF, 0xFF, 0xFF, 0xFF, 0xF1, 0xFF, 0xFC, 0xFE, 0xFF,
    0x7F, 0xFF, 0xFF, 0xFF, 0xFF, 0xFE, 0xFB, 0xFE, 0xFF, 0xFF, 0xFB, 0xFF,
    0xFF, 0xFF, 0xFE, 0xFF, 0xFF, 0xFF, 0xFE, 0xFB, 0xFF, 0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xEF, 0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xFF, 0xFE, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xF9, 0xE0, 0xFE, 0x0C, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x01, 0xFF, 0xFF, 0xFF, 0xFB, 0xFC, 0x00, 0x00, 0xFF,
};

/* 1 if the Macintosh Plus ROM implements this trap (flag bits are ignored). */
static inline int plusrom_trap_in_rom(uint16_t trap)
{
    unsigned i;
    if ((trap & 0xF000) != 0xA000) return 0;
    if (trap & 0x0800) { i = trap & 0x3FF; if (i >= 512) return 0; }
    else i = 512 + (trap & 0xFF);
    return (plusrom_trap_bitmap[i >> 3] >> (7 - (i & 7))) & 1;
}

/* Which machine are we on? ROM version word at ROMBase+8: $0075 Plus, $0276 SE. */
#define PLUSROM_MACHINE_PLUS 1
#define PLUSROM_MACHINE_SE   2
static inline int plusrom_machine(void)
{
    const uint8_t *rom = *(const uint8_t * const *)0x2AE;      /* ROMBase */
    return rom[9] == 0x76 ? PLUSROM_MACHINE_SE : PLUSROM_MACHINE_PLUS;
}
static inline const char *plusrom_machine_name(void)
{
    return plusrom_machine() == PLUSROM_MACHINE_SE ? "Macintosh SE" : "Macintosh Plus";
}

/* The Toolbox trap table is at $0C00 on the Plus and $0E00 on the SE (where
 * $0C00 holds the SCSI globals). OS traps are at $0400 on both. */
static inline void **plusrom_tool_table(void)
{
    return (void **)(uintptr_t)(plusrom_machine() == PLUSROM_MACHINE_SE ? 0x0E00 : 0x0C00);
}
static inline void **plusrom_trap_slot(uint16_t trap)
{
    if (trap & 0x0800) return plusrom_tool_table() + (trap & 0x1FF);
    return (void **)(uintptr_t)0x0400 + (trap & 0xFF);
}
static inline void *plusrom_trap_address(uint16_t trap) { return *plusrom_trap_slot(trap); }

